#!/usr/bin/env bash
#
# The contract: what a desktop that drives jayos-moonlander may rely on.
#
#   tools/contract.sh            compare contract/ with what the code says
#   tools/contract.sh --write    rewrite the generated files of contract/
#
# Exit 0: contract/ is what the code says (or was rewritten). 1: it is not,
# and the lines above say which file. 2: could not run -- a source this reads
# is missing -- which is not the same answer as "current".
#
# Four files are made here, from the code and never by hand: a contract
# written by hand beside the code would be a second description of it, and the
# two would drift. verbs.txt from the dispatch of src/jayos-moonlander,
# layers-verbs.txt from the verbs jayos-keymapp-layers' main() names to
# emit::unknown_command, osd-icons.txt from the ICON_ constants of
# jayos-moonlander-osd -- the names it hands the desktop's osd.sh, which JayOS's
# OSD draws a glyph and a colour for -- and steps.txt from
# packaging/steps.sh's dispatch.
#
# files.txt and runtime.txt are the other kind: promises, written by hand, of
# where the package puts things and which files the daemon writes and reads,
# which JayOS reads to know where the programs are and what to draw from.
# Generating them from the code would make them say whatever the code did;
# tests/shell/test-packaging.sh runs `steps.sh package` and holds what lands
# to files.txt, both ways, and tests/shell/test-osd.sh holds the daemon to
# runtime.txt. README.md and VERSION are written by hand too.
#
# jayos-bluetooth's tools/contract.sh is the model.

set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
CLI="$ROOT/src/jayos-moonlander"
LAYERS="$ROOT/src/bin/jayos-keymapp-layers.rs"
OSD="$ROOT/src/bin/jayos-moonlander-osd.rs"
STEPS="$ROOT/packaging/steps.sh"
OUT="$ROOT/contract"

for f in "$CLI" "$LAYERS" "$OSD" "$STEPS"; do
    [[ -r "$f" ]] || { echo "contract not exercised: cannot read ${f#"$ROOT"/}" >&2; exit 2; }
done

WORK="$(mktemp -d "${TMPDIR:-/tmp}/jayos-moonlander-contract.XXXXXX")" || exit 2
trap 'rm -rf "$WORK"' EXIT

header() { # header <what> <made from>
    printf '# %s\n# Generated by tools/contract.sh from %s; do not edit.\n' "$1" "$2"
}

die() { echo "contract.sh: $*" >&2; exit 1; }

generate() { # generate <dir>
    local dir=$1 verbs layers icons steps
    # The dispatch's arms, four spaces in and a lone word before `)`: the
    # `case "${1:-status}"` block is the only one at that depth whose arms are
    # bare words, and `*)` is no verb.
    verbs=$(sed -n '/^case "\${1:-status}" in$/,/^esac$/p' "$CLI" | sed -n -E 's/^    ([a-z-]+)\)$/\1/p')
    [[ -n "$verbs" ]] || die "read no verbs from src/jayos-moonlander's dispatch"
    # The one list main() hands emit::unknown_command, comments dropped first
    # so a name in a comment is not a verb.
    layers=$(sed 's|//.*$||' "$LAYERS" | grep -oE 'emit::unknown_command\(&args\.program, other, &\[[^]]*\]' \
        | grep -oE '"[^"]+"' | tr -d '"')
    [[ -n "$layers" ]] || die "read no verbs from src/bin/jayos-keymapp-layers.rs's main()"
    # Each `const ICON_<NAME>: &str = "<name>";`, in the file's order.
    icons=$(sed 's|//.*$||' "$OSD" | sed -n -E 's/^const ICON_[A-Z_]+: &str = "([^"]+)";$/\1/p')
    [[ -n "$icons" ]] || die "read no ICON_ constants from src/bin/jayos-moonlander-osd.rs"
    steps=$(sed -n -E 's/^    ([a-z]+)\)[[:space:]]+step_[a-z]+.*;;$/\1/p' "$STEPS")
    [[ -n "$steps" ]] || die "read no verbs from packaging/steps.sh's dispatch"

    { header "The verbs of jayos-moonlander, the command in /usr/bin, in its dispatch's order." \
          "src/jayos-moonlander's dispatch"
      printf '%s\n' "$verbs"; } > "$dir/verbs.txt"
    { header "The verbs of jayos-keymapp-layers, in /usr/bin; with none it prints what names does." \
          "the list main() in src/bin/jayos-keymapp-layers.rs names"
      printf '%s\n' "$layers"; } > "$dir/layers-verbs.txt"
    { header "The icon names jayos-moonlander-osd hands osd.sh's show, in its source's order." \
          "the ICON_ constants of src/bin/jayos-moonlander-osd.rs"
      printf '%s\n' "$icons"; } > "$dir/osd-icons.txt"
    { header "The verbs of packaging/steps.sh, which JayOS's recipe calls, with their arguments." \
          "packaging/steps.sh's dispatch"
      local v
      while IFS= read -r v; do
          if [[ "$v" == package ]]; then printf 'package <pkgdir>\n'; else printf '%s\n' "$v"; fi
      done <<<"$steps"; } > "$dir/steps.txt"
}

mkdir -p "$WORK/new"
generate "$WORK/new"

if [[ "${1:-}" == --write ]]; then
    cp "$WORK/new"/*.txt "$OUT/" || die "could not write contract/"
    echo "  contract/: verbs.txt, layers-verbs.txt, osd-icons.txt and steps.txt rewritten"
    exit 0
fi
[[ -z "${1:-}" ]] || { echo "usage: tools/contract.sh [--write]" >&2; exit 2; }

status=0
for f in "$WORK/new"/*.txt; do
    n=${f##*/}
    if [[ ! -f "$OUT/$n" ]]; then
        echo "  contract/$n is missing; tools/contract.sh --write makes it"
        status=1
    elif ! cmp -s "$f" "$OUT/$n"; then
        echo "  contract/$n is not what the code says:"
        diff "$OUT/$n" "$f" | sed 's/^/    /'
        status=1
    fi
done
for f in README.md VERSION files.txt runtime.txt; do
    [[ -f "$OUT/$f" ]] || { echo "  contract/$f, written by hand, is missing"; status=1; }
done
(( status == 0 )) && echo "  contract/ is what the code says"
exit "$status"
